#!/usr/bin/env python3
"""把 Claude Code 会话 JSONL 导出为可读 Markdown（只保留对话正文）。"""
import sys, json, os, glob
from datetime import datetime

SRC = "/home/dushuangquan/.claude/projects/-home-dushuangquan-code-OpenVela-contest2026-106-VelaGoGoGo"
OUT = os.path.expanduser("~/claude_exports/VelaGoGoGo")


def extract_text(content):
    """从 message.content 里抽取纯文本，跳过 thinking / tool_use / tool_result。"""
    if isinstance(content, str):
        return content.strip()
    if isinstance(content, list):
        parts = []
        for item in content:
            if isinstance(item, dict) and item.get("type") == "text":
                parts.append(item.get("text", "").strip())
        return "\n\n".join(p for p in parts if p)
    return ""


def is_injected(text):
    """过滤掉系统注入的伪 user 消息（命令输出、reminder 等）。"""
    if not text:
        return True
    head = text.lstrip()[:40]
    return head.startswith("<") or head.startswith("Caveat:") or head.startswith("[Request interrupted")


def process(path):
    title = None
    turns = []  # (role, text)
    with open(path, encoding="utf-8") as f:
        for line in f:
            try:
                o = json.loads(line)
            except Exception:
                continue
            t = o.get("type")
            if t == "ai-title" and not title:
                title = o.get("title") or o.get("aiTitle")
            if t not in ("user", "assistant"):
                continue
            msg = o.get("message")
            if not isinstance(msg, dict):
                continue
            role = msg.get("role")
            text = extract_text(msg.get("content"))
            if role == "user" and is_injected(text):
                continue
            if not text:
                continue
            turns.append((role, text))
    return title, turns


def main():
    os.makedirs(OUT, exist_ok=True)
    files = sorted(glob.glob(os.path.join(SRC, "*.jsonl")), key=os.path.getmtime)
    count = 0
    index = []
    for path in files:
        title, turns = process(path)
        if not turns:
            continue
        sid = os.path.splitext(os.path.basename(path))[0]
        mtime = datetime.fromtimestamp(os.path.getmtime(path)).strftime("%Y%m%d")
        safe_title = "".join(c if c.isalnum() or c in " -_一二三四五六七八九十" else "_"
                             for c in (title or ""))[:40].strip() or sid[:8]
        fname = f"{mtime}_{safe_title}.md"
        out_path = os.path.join(OUT, fname)
        with open(out_path, "w", encoding="utf-8") as w:
            w.write(f"# {title or sid}\n\n")
            w.write(f"> Session: `{sid}`  |  最后修改: {mtime}  |  共 {len(turns)} 条\n\n---\n\n")
            for role, text in turns:
                who = "🧑 我" if role == "user" else "🤖 Claude"
                w.write(f"## {who}\n\n{text}\n\n")
        count += 1
        index.append(f"- [{title or sid}]({fname}) — {mtime}, {len(turns)} 条")
        print(f"  ✓ {fname}  ({len(turns)} turns)")

    with open(os.path.join(OUT, "README.md"), "w", encoding="utf-8") as w:
        w.write(f"# VelaGoGoGo Claude 对话导出\n\n共 {count} 个会话，导出于 {datetime.now():%Y-%m-%d %H:%M}\n\n")
        w.write("\n".join(index))

    print(f"\n完成：{count} 个会话 → {OUT}")


if __name__ == "__main__":
    main()
